-- British -> American spelling pairs for spelling_variants (see
-- 20261010180000_spelling_variants.sql), then tags already stored are folded
-- to American spelling, originals saved in tag_merge_backup (batch 'spelling-us').
--
-- Generated by scripts/varcon_to_sql.py from VarCon varcon.txt
-- (sha256 75af63da46ec12d7eb14b9f1ba8d3898d484dd6872755b73c921b215875a3629), SCOWL level <= 80: 9281 pairs.
-- Filtered from VarCon, Copyright 2000-2020 Kevin Atkinson and Benjamin Titze;
-- original lists Copyright 1993 Geoff Kuenning. See THIRD_PARTY_NOTICES.md.

select 'spelling-us', 'papers', id, tags from public.papers
 where tags is distinct from public.clean_tags(tags)
union all
select 'spelling-us', 'paper_posts', id, tags from public.paper_posts
 where tags is distinct from public.clean_tags(tags)
union all
select 'spelling-us', 'removed_posts', id, tags from public.removed_posts
 where tags is distinct from public.clean_tags(tags)
union all
select 'spelling-us', 'profiles', id, interests from public.profiles
 where interests is distinct from public.clean_tags(interests);

select * from public.apply_tag_cleanup();
